#nullable enable
using Alba;
using Campaigns.Contracts;
using Campaigns.Slices.Campaigns;
using Microsoft.AspNetCore.Mvc;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>
/// Pattern: command. Status: ready.
///
/// The one slice whose rule lives in ANOTHER stream: "a message cannot be queued to a closed campaign" is
/// a fact about the Campaign stream, and this slice writes the Message stream. Read one, write one.
/// </summary>
public sealed class QueueMessageTests(AppFixture fixture) : IntegrationContext(fixture)
{
    internal static readonly Guid SenderId = Guid.Parse("33333333-3333-3333-3333-333333333333");

    internal static string[] TwoRecipients => ["a@example.com", "b@example.com"];

    private async Task<(bool Ok, string? Rule)> Queue(
        Guid messageId, Guid campaignId, string[]? recipients = null)
    {
        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new QueueMessage(
                    messageId, campaignId, SenderId, "Subject", recipients ?? TwoRecipients))
                .ToUrl(QueueMessageEndpoint.Route);
            x.IgnoreStatusCode();
        });

        if (result.Context.Response.StatusCode == 200) return (true, null);

        // A periphery failure is not ProblemDetails-with-a-title, so read the text and look for the rule
        // name rather than assuming one shape covers both refusal kinds.
        var body = await result.ReadAsTextAsync();
        if (body.Contains("RecipientsRequired")) return (false, "RecipientsRequired");

        return (false, (await result.ReadAsJsonAsync<ProblemDetails>())?.Title);
    }

    // a message can be queued to an open campaign
    //   GIVEN CampaignOpened
    //   WHEN  QueueMessage
    //   THEN  MessageQueued
    [Fact]
    public async Task AMessageCanBeQueuedToAnOpenCampaign()
    {
        var campaignId = SeedData.CampaignId;
        var messageId = SeedData.MessageId;
        await Given(campaignId, new CampaignOpened(campaignId, "January", SeedData.SeededAt));

        var (ok, rule) = await Queue(messageId, campaignId);

        ok.ShouldBeTrue(rule);
        var queued = (await EventsFor(messageId)).ShouldHaveSingleItem().ShouldBeOfType<MessageQueued>();
        queued.CampaignId.ShouldBe(campaignId);
        queued.Recipients.Length.ShouldBe(2);
    }

    // a message with no recipients is refused
    //   GIVEN —
    //   WHEN  QueueMessage
    //   THEN  error: RecipientsRequired    (enforce="periphery")
    [Fact]
    public async Task AMessageWithNoRecipientsIsRefused()
    {
        var campaignId = SeedData.CampaignId;
        var messageId = Guid.NewGuid();
        await Given(campaignId, new CampaignOpened(campaignId, "January", SeedData.SeededAt));

        var (ok, rule) = await Queue(messageId, campaignId, []);

        ok.ShouldBeFalse();
        rule.ShouldBe("RecipientsRequired");
        (await EventsFor(messageId)).ShouldBeEmpty();
    }

    // a message cannot be queued to a closed campaign
    //   GIVEN CampaignOpened, CampaignClosed
    //   WHEN  QueueMessage
    //   THEN  error: CampaignNotOpen    (enforce="aggregate")
    [Fact]
    public async Task AMessageCannotBeQueuedToAClosedCampaign()
    {
        var campaignId = SeedData.CampaignId;
        var messageId = Guid.NewGuid();
        await Given(campaignId,
            new CampaignOpened(campaignId, "January", SeedData.SeededAt),
            new CampaignClosed(campaignId, SeedData.SeededAt));

        var (ok, rule) = await Queue(messageId, campaignId);

        ok.ShouldBeFalse();
        rule.ShouldBe("CampaignNotOpen");
        (await EventsFor(messageId)).ShouldBeEmpty();
    }
}
